      if (!p || !p.headline) { box.hidden = true; return; }                     // unknown → the page keeps its own state
      if (current && current.variation.variation_id === variation.variation_id && !box.hidden) return;   // Woo re-fires found_variation: don't wipe what she is typing
      current = { variation: variation, promise: p };
      var themePays = !!document.querySelector('#fx-trust .fx-trust-pagos, .fx-trust-pagos');   // the site's trust box already shows secure payment + card logos
      var trust = (data.trust || []).filter(function (t) { return t.status === 'known' && !(themePays && t.key === 'pago_seguro'); }).map(function (t) { return '<span>' + esc(t.text) + '</span>'; }).join('');
      var size = Object.keys(variation.attributes || {}).map(function (k) { return variation.attributes[k]; }).filter(Boolean).pop() || '';
      if (mk === 'MX' && /^\d+(\.5)?$/.test(size)) size = String(Number(size) - 13);   // talla mexicana (como en la PDP)
